import Foundation

/// The one privacy rule every clipboard history in Atelier follows. Password managers and
/// system tools mark what should never be kept (nspasteboard.org); such a copy is skipped.
public enum ClipboardPrivacy {
    /// Pasteboard types that mean "do not record this".
    public static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    /// Whether a copy with these pasteboard types may be kept. No types at all is not kept.
    public static func mayKeep(types: [String]?) -> Bool {
        guard let types else { return false }
        return skippedTypes.isDisjoint(with: types)
    }

    /// The text to keep from a copy, or nil when it is private or blank.
    public static func keptText(types: [String]?, text: String?, limit: Int = 2000) -> String? {
        guard mayKeep(types: types),
              let trimmed = text?.trimmingCharacters(in: .whitespacesAndNewlines), !trimmed.isEmpty else { return nil }
        return String(trimmed.prefix(limit))
    }
}

/// Apple's hot corner actions, the values com.apple.dock keeps in `wvous-<corner>-corner`.
public enum AppleHotCorner {
    /// Every value System Settings offers, plus the ones older releases wrote.
    public static let actions: [(Int, String)] = [
        (1, "Nothing"), (2, "Mission Control"), (3, "App Windows"), (4, "Desktop"), (5, "Start Screen Saver"),
        (6, "Disable Screen Saver"), (10, "Sleep Display"), (11, "Launchpad"), (12, "Notification Centre"),
        (13, "Lock Screen"), (14, "Quick Note"),
    ]

    /// 0 and an absent key both mean nothing happens; they show as Nothing.
    public static func normalized(_ value: Int) -> Int { value <= 0 ? 1 : value }

    /// The menu for a corner that holds `current`. A value Atelier does not know (Dashboard's 7
    /// from an old macOS) is listed under its number rather than shown as a blank.
    public static func options(current: Int) -> [(Int, String)] {
        let value = normalized(current)
        if actions.contains(where: { $0.0 == value }) { return actions }
        return actions + [(value, "Other (\(value))")]
    }

    /// Changes only the action. The corner's modifier (⌘, ⌥…) is the user's and stays; it is
    /// set to none only when the corner never had one.
    public static func set(_ corner: String, to value: Int, in plist: inout [String: Any]) {
        plist["wvous-\(corner)-corner"] = normalized(value)
        if plist["wvous-\(corner)-modifier"] == nil { plist["wvous-\(corner)-modifier"] = 0 }
    }
}
